-- Blog-post QUALIFY (Snowflake) vs portable emulation (real SQLite/PostgreSQL)
-- Snowflake:  SELECT name, RANK() OVER (ORDER BY h DESC) AS rnk FROM devs QUALIFY rnk <= 3;
-- Portable:
SELECT name, rnk FROM (
  SELECT name, RANK() OVER (ORDER BY hours_studied DESC) AS rnk
  FROM developers
) WHERE rnk <= 3;

